<div class="wp-block-wdl-paid-block-custom-title-10 paid-block-custom-title-10 position_center size_l" id="staff"><h2 class="ttl"><span class="text_wrap"><span class="sub" style="color:var(--color-main)">STAFF</span><span class="main">担当者のご紹介</span></span><span class="bd" style="background-color:var(--color-main);height:2px;margin-top:0.1em"></span></h2></div>
